package io.github.gamemessagepopups;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class GameMessageOverlay extends Overlay
{
	private static final int VIEWPORT_MARGIN = 8;
	private static final List<String> PREVIEW = List.of("You can't do that right now.");

	final MessageQueue messages = new MessageQueue();
	private final float[] opacities = new float[MessageQueue.MAX_VISIBLE];
	private volatile Appearance appearance;
	private volatile Rectangle safeViewport = new Rectangle();
	private List<MessageQueue.Popup> currentPopups = List.of();
	private List<String> currentTexts = List.of();
	private List<String> layoutTexts = List.of();
	private Appearance layoutAppearance;
	private int layoutWidth;
	private int layoutHeight;
	private MessageLayout layout = MessageLayout.EMPTY;

	GameMessageOverlay(GameMessagePopupsPlugin plugin, GameMessagePopupsConfig config)
	{
		super(plugin);
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setSnappable(false);
		updateAppearance(config);
	}

	void updateAppearance(GameMessagePopupsConfig config)
	{
		appearance = new Appearance(config);
	}

	void prepare(long now, Rectangle gameViewport, Dimension canvas)
	{
		Appearance current = appearance;
		Rectangle viewport = insetViewport(gameViewport, canvas);
		safeViewport = viewport;
		List<MessageQueue.Popup> live = messages.advance(now);

		List<String> texts = PREVIEW;
		if (current.preview)
		{
			opacities[0] = 1f;
		}
		else
		{
			if (live != currentPopups)
			{
				currentPopups = live;
				currentTexts = new ArrayList<>(live.size());
				for (MessageQueue.Popup popup : live)
				{
					currentTexts.add(popup.text);
				}
			}
			texts = currentTexts;
			for (int index = 0; index < live.size(); index++)
			{
				opacities[index] = live.get(index).opacity(now);
			}
		}

		int width = Math.min(viewport.width, current.maxWidth);
		int height = viewport.height;
		if (!texts.equals(layoutTexts) || current != layoutAppearance || width != layoutWidth || height != layoutHeight)
		{
			layout = MessageLayout.wrap(texts, current.font, current.color, current.outline, current.shadow, width, height);
			layoutTexts = texts;
			layoutAppearance = current;
			layoutWidth = width;
			layoutHeight = height;
		}

		// RuneLite clamps the position before render(), using the size already in getBounds().
		Rectangle bounds = getBounds();
		bounds.setSize(layout.size);
		if (getPreferredLocation() == null)
		{
			int x = viewport.x + Math.round(viewport.width * current.horizontalPercent / 100f) - bounds.width / 2;
			int y = viewport.y + Math.round(viewport.height * current.verticalPercent / 100f);
			bounds.setLocation(
				clamp(x, viewport.x, viewport.x + viewport.width - bounds.width),
				clamp(y, viewport.y, viewport.y + viewport.height - bounds.height));
		}
	}

	@Override
	public Rectangle getParentBounds()
	{
		return safeViewport;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (layout == MessageLayout.EMPTY)
		{
			return null;
		}

		Graphics2D textGraphics = (Graphics2D) graphics.create();
		try
		{
			layout.paint(textGraphics, opacities);
		}
		finally
		{
			textGraphics.dispose();
		}
		return layout.size;
	}

	private static Rectangle insetViewport(Rectangle gameViewport, Dimension canvas)
	{
		Rectangle viewport = gameViewport.intersection(new Rectangle(canvas));
		if (viewport.width <= 2 * VIEWPORT_MARGIN || viewport.height <= 2 * VIEWPORT_MARGIN)
		{
			return new Rectangle();
		}
		viewport.grow(-VIEWPORT_MARGIN, -VIEWPORT_MARGIN);
		return viewport;
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}

	private static final class Appearance
	{
		private final Font font;
		private final Color color;
		private final boolean outline;
		private final boolean shadow;
		private final int maxWidth;
		private final int horizontalPercent;
		private final int verticalPercent;
		private final boolean preview;

		private Appearance(GameMessagePopupsConfig config)
		{
			String family = config.fontFamily().resolve(config.customFontFamily());
			font = new Font(family, config.bold() ? Font.BOLD : Font.PLAIN,
				clamp(config.fontSize(), GameMessagePopupsConfig.MIN_FONT_SIZE, GameMessagePopupsConfig.MAX_FONT_SIZE));
			color = config.textColor();
			outline = config.outline();
			shadow = config.shadow();
			maxWidth = clamp(config.maxTextWidth(), GameMessagePopupsConfig.MIN_TEXT_WIDTH, GameMessagePopupsConfig.MAX_TEXT_WIDTH);
			horizontalPercent = clamp(config.horizontalPercent(), 0, 100);
			verticalPercent = clamp(config.verticalPercent(), 0, 100);
			preview = config.preview();
		}
	}
}

package io.github.gamemessagepopups;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(GameMessagePopupsConfig.GROUP)
public interface GameMessagePopupsConfig extends Config
{
	String GROUP = "gameMessagePopups";
	String FONT_FAMILY = "fontFamilyChoice";
	String CUSTOM_FONT_FAMILY = "customFontFamily";
	int MIN_FONT_SIZE = 10;
	int MAX_FONT_SIZE = 48;
	int MAX_DELAY_MS = 5000;
	int MIN_HOLD_MS = 100;
	int MAX_HOLD_MS = 10000;
	int MAX_FADE_MS = 5000;
	int MIN_TEXT_WIDTH = 120;
	int MAX_TEXT_WIDTH = 900;

	@ConfigSection(name = "Position", description = "Place the popups in the game viewport", position = 0)
	String POSITION = "position";

	@ConfigSection(name = "Appearance", description = "Style and size of the popup text", position = 1)
	String APPEARANCE = "appearance";

	@ConfigSection(name = "Timing", description = "Delay, hold, and fade for new messages", position = 2)
	String TIMING = "timing";

	@ConfigSection(name = "Messages", description = "Which game messages to show", position = 3)
	String MESSAGES = "messages";

	@ConfigItem(keyName = "preview", name = "Preview", description = "Show a persistent sample while logged in. Hold Alt and drag it to position the overlay.", position = 0, section = POSITION)
	default boolean preview()
	{
		return false;
	}

	@Range(max = 100)
	@ConfigItem(keyName = "horizontalPercent", name = "Horizontal position (%)", description = "Default text center, from left (0) to right (100). Alt + right-click the overlay to restore this position after dragging.", position = 1, section = POSITION)
	default int horizontalPercent()
	{
		return 50;
	}

	@Range(max = 100)
	@ConfigItem(keyName = "verticalPercent", name = "Vertical position (%)", description = "Default distance from the top of the viewport. Applies when the overlay has no saved drag position.", position = 2, section = POSITION)
	default int verticalPercent()
	{
		return 18;
	}

	@ConfigItem(keyName = FONT_FAMILY, name = "Font family", description = "Choose a popup font family. System fonts must be installed on your computer.", position = 0, section = APPEARANCE)
	default PopupFontFamily fontFamily()
	{
		return PopupFontFamily.SANS_SERIF;
	}

	@ConfigItem(keyName = "bold", name = "Bold", description = "Draw popup text in bold.", position = 1, section = APPEARANCE)
	default boolean bold()
	{
		return true;
	}

	@ConfigItem(keyName = "outline", name = "Outline", description = "Draw a dark outline around the text.", position = 2, section = APPEARANCE)
	default boolean outline()
	{
		return true;
	}

	@ConfigItem(keyName = "shadow", name = "Shadow", description = "Draw a drop shadow behind the text.", position = 3, section = APPEARANCE)
	default boolean shadow()
	{
		return false;
	}

	@Range(min = MIN_FONT_SIZE, max = MAX_FONT_SIZE)
	@ConfigItem(keyName = "fontSize", name = "Font size", description = "Text size in game pixels.", position = 4, section = APPEARANCE)
	default int fontSize()
	{
		return 18;
	}

	@ConfigItem(keyName = "textColor", name = "Text color", description = "Popup text color.", position = 5, section = APPEARANCE)
	default Color textColor()
	{
		return new Color(255, 83, 74);
	}

	@Range(min = MIN_TEXT_WIDTH, max = MAX_TEXT_WIDTH)
	@ConfigItem(keyName = "maxTextWidth", name = "Maximum width (px)", description = "Wrap text at this width or the available viewport width, whichever is smaller.", position = 6, section = APPEARANCE)
	default int maxTextWidth()
	{
		return 420;
	}

	@ConfigItem(keyName = CUSTOM_FONT_FAMILY, name = "Custom font family", description = "An installed font family to use when Font family is set to Custom.", position = 7, section = APPEARANCE)
	default String customFontFamily()
	{
		return "";
	}

	@Range(max = MAX_DELAY_MS)
	@ConfigItem(keyName = "delayMs", name = "Delay (ms)", description = "Minimum wait after a message arrives.", position = 0, section = TIMING)
	default int delayMs()
	{
		return 0;
	}

	@Range(min = MIN_HOLD_MS, max = MAX_HOLD_MS)
	@ConfigItem(keyName = "holdMs", name = "Display time (ms)", description = "How long text stays fully visible once it appears.", position = 1, section = TIMING)
	default int holdMs()
	{
		return 1600;
	}

	@Range(max = MAX_FADE_MS)
	@ConfigItem(keyName = "fadeMs", name = "Fade-out (ms)", description = "How long text takes to fade after the display time. Set to 0 for an instant disappearance.", position = 2, section = TIMING)
	default int fadeMs()
	{
		return 650;
	}

	@ConfigItem(keyName = "showFilteredMessages", name = "Show filterable messages", description = "Include repetitive game messages of type SPAM, even when Game Chat is filtered.", position = 0, section = MESSAGES)
	default boolean showFilteredMessages()
	{
		return false;
	}

	@ConfigItem(keyName = "showExamines", name = "Show examines", description = "Include item, NPC and object descriptions from Examine.", position = 1, section = MESSAGES)
	default boolean showExamines()
	{
		return false;
	}
}

package io.github.gamemessagepopups;

import com.google.inject.Provides;
import java.awt.Rectangle;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Game Message Popups",
	description = "Shows game chat messages as fading text over the viewport",
	tags = {"game", "chat", "notifications", "overlay"}
)
public final class GameMessagePopupsPlugin extends Plugin
{
	private static final String LEGACY_FONT_FAMILY = "fontFamily";
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GameMessagePopupsConfig config;

	private volatile GameMessageOverlay overlay;

	@Provides
	GameMessagePopupsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GameMessagePopupsConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateFontFamily();
		GameMessageOverlay newOverlay = new GameMessageOverlay(this, config);
		overlayManager.add(newOverlay);
		overlay = newOverlay;
	}

	@Override
	protected void shutDown()
	{
		GameMessageOverlay oldOverlay = overlay;
		overlay = null;
		overlayManager.remove(oldOverlay);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		GameMessageOverlay current = overlay;
		if (current == null || !isInWorld(client.getGameState()) || event.getMessage() == null
			|| !accepts(event.getType(), config))
		{
			return;
		}

		String message = cleanMessage(event.getMessage());
		if (!message.isEmpty())
		{
			current.messages.add(message, System.nanoTime(), new MessageQueue.Timing(
				config.delayMs(), config.holdMs(), config.fadeMs()));
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		GameMessageOverlay current = overlay;
		if (current != null && client.getGameState() == GameState.LOGGED_IN)
		{
			Rectangle viewport = new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
				client.getViewportWidth(), client.getViewportHeight());
			current.prepare(System.nanoTime(), viewport, client.getRealDimensions());
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		GameMessageOverlay current = overlay;
		if (current != null && GameMessagePopupsConfig.GROUP.equals(event.getGroup()))
		{
			current.updateAppearance(config);
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		migrateFontFamily();
		GameMessageOverlay current = overlay;
		if (current != null)
		{
			current.updateAppearance(config);
		}
	}

	private void migrateFontFamily()
	{
		String group = GameMessagePopupsConfig.GROUP;
		String previousFamily = configManager.getConfiguration(group, LEGACY_FONT_FAMILY);
		if (previousFamily == null)
		{
			return;
		}

		if (config.fontFamily() == PopupFontFamily.SANS_SERIF)
		{
			PopupFontFamily choice = PopupFontFamily.fromSavedName(previousFamily);
			if (choice == PopupFontFamily.CUSTOM && config.customFontFamily().isBlank())
			{
				configManager.setConfiguration(group, GameMessagePopupsConfig.CUSTOM_FONT_FAMILY, previousFamily.strip());
			}
			configManager.setConfiguration(group, GameMessagePopupsConfig.FONT_FAMILY, choice);
		}
		configManager.unsetConfiguration(group, LEGACY_FONT_FAMILY);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameMessageOverlay current = overlay;
		if (current != null && !isInWorld(event.getGameState()))
		{
			current.messages.clear();
		}
	}

	static boolean accepts(ChatMessageType type, GameMessagePopupsConfig config)
	{
		if (type == null)
		{
			return false;
		}

		switch (type)
		{
			case GAMEMESSAGE:
			case ENGINE:
				return true;
			case SPAM:
				return config.showFilteredMessages();
			case ITEM_EXAMINE:
			case NPC_EXAMINE:
			case OBJECT_EXAMINE:
				return config.showExamines();
			default:
				return false;
		}
	}

	static String cleanMessage(String message)
	{
		String plainText = Text.unescapeJagex(message).replace('\u00a0', ' ');
		return WHITESPACE.matcher(plainText).replaceAll(" ").strip();
	}

	private static boolean isInWorld(GameState state)
	{
		return state == GameState.LOGGED_IN || state == GameState.LOADING;
	}
}

package io.github.gamemessagepopups;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.font.FontRenderContext;
import java.awt.font.LineBreakMeasurer;
import java.awt.font.LineMetrics;
import java.awt.font.TextAttribute;
import java.awt.font.TextLayout;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.text.AttributedString;
import java.util.ArrayList;
import java.util.List;

final class MessageLayout
{
	private static final int PADDING = 4;
	private static final int MAX_LINES_PER_MESSAGE = 4;
	private static final String ELLIPSIS = "…";
	private static final int SHADOW_OFFSET = 2;
	private static final Color SHADOW_COLOR = new Color(0, 0, 0, 175);
	private static final Color OUTLINE_COLOR = new Color(22, 9, 9);
	private static final BasicStroke OUTLINE = new BasicStroke(2.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final FontRenderContext FONT_CONTEXT = new FontRenderContext(null, true, true);
	static final MessageLayout EMPTY = new MessageLayout(new Dimension(), List.of());

	final Dimension size;
	private final List<Block> blocks;

	private MessageLayout(Dimension size, List<Block> blocks)
	{
		this.size = size;
		this.blocks = blocks;
	}

	static MessageLayout wrap(List<String> messages, Font font, Color color, boolean outline, boolean shadow, int maxWidth, int maxHeight)
	{
		if (messages.isEmpty() || maxWidth <= 2 * PADDING)
		{
			return EMPTY;
		}

		LineMetrics metrics = font.getLineMetrics("Ag", FONT_CONTEXT);
		int lineHeight = (int) Math.ceil(metrics.getHeight()) + 2;
		int availableRows = (maxHeight - 2 * PADDING) / lineHeight;
		if (availableRows < 1)
		{
			return EMPTY;
		}

		int top = 0;
		int width = 0;
		List<Block> blocks = new ArrayList<>();
		int first = Math.max(0, messages.size() - availableRows);
		for (int index = first; index < messages.size(); index++)
		{
			int subsequentMessages = messages.size() - index - 1;
			int rowLimit = Math.min(MAX_LINES_PER_MESSAGE, availableRows - subsequentMessages);
			List<TextLayout> lines = wrapMessage(messages.get(index), font, maxWidth - 2 * PADDING, rowLimit);
			BufferedImage image = renderBlock(lines, color, outline, shadow, maxWidth, lineHeight, metrics.getAscent());
			blocks.add(new Block(index, top, image));
			width = Math.max(width, image.getWidth());
			top += lines.size() * lineHeight;
			availableRows -= lines.size();
		}

		return new MessageLayout(new Dimension(width, top + 2 * PADDING), blocks);
	}

	void paint(Graphics2D graphics, float[] opacities)
	{
		for (Block block : blocks)
		{
			float opacity = opacities[block.messageIndex];
			if (opacity > 0)
			{
				graphics.setComposite(AlphaComposite.SrcOver.derive(opacity));
				graphics.drawImage(block.image, (size.width - block.image.getWidth()) / 2, block.top, null);
			}
		}
	}

	private static BufferedImage renderBlock(List<TextLayout> lines, Color color, boolean outline, boolean shadow,
		int maxWidth, int lineHeight, float ascent)
	{
		int textWidth = 0;
		for (TextLayout line : lines)
		{
			textWidth = Math.max(textWidth, (int) Math.ceil(line.getBounds().getWidth()));
		}

		int width = Math.min(maxWidth, textWidth + 2 * PADDING);
		int height = lines.size() * lineHeight + 2 * PADDING;
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB_PRE);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setStroke(OUTLINE);
			float baseline = PADDING + ascent;
			for (TextLayout line : lines)
			{
				double x = width / 2.0 - line.getBounds().getCenterX();
				Shape glyph = line.getOutline(AffineTransform.getTranslateInstance(x, baseline));
				if (shadow)
				{
					graphics.setColor(SHADOW_COLOR);
					graphics.translate(SHADOW_OFFSET, SHADOW_OFFSET);
					graphics.fill(glyph);
					graphics.translate(-SHADOW_OFFSET, -SHADOW_OFFSET);
				}
				if (outline)
				{
					graphics.setColor(OUTLINE_COLOR);
					graphics.draw(glyph);
				}
				graphics.setColor(color);
				graphics.fill(glyph);
				baseline += lineHeight;
			}
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static List<TextLayout> wrapMessage(String text, Font font, int width, int rowLimit)
	{
		AttributedString attributed = new AttributedString(text);
		attributed.addAttribute(TextAttribute.FONT, font);
		LineBreakMeasurer measurer = new LineBreakMeasurer(attributed.getIterator(), FONT_CONTEXT);
		List<TextLayout> wrapped = new ArrayList<>(rowLimit);
		while (measurer.getPosition() < text.length() && wrapped.size() < rowLimit)
		{
			int start = measurer.getPosition();
			TextLayout line = measurer.nextLayout(width);
			if (wrapped.size() == rowLimit - 1 && measurer.getPosition() < text.length())
			{
				measurer.setPosition(start);
				TextLayout ellipsis = new TextLayout(ELLIPSIS, font, FONT_CONTEXT);
				float prefixWidth = width - ellipsis.getAdvance();
				if (prefixWidth > 0)
				{
					int end = measurer.nextOffset(prefixWidth);
					line = new TextLayout(text.substring(start, end).stripTrailing() + ELLIPSIS, font, FONT_CONTEXT);
				}
				else
				{
					line = ellipsis;
				}
			}
			wrapped.add(line);
		}
		return wrapped;
	}

	private static final class Block
	{
		private final int messageIndex;
		private final int top;
		private final BufferedImage image;

		private Block(int messageIndex, int top, BufferedImage image)
		{
			this.messageIndex = messageIndex;
			this.top = top;
			this.image = image;
		}
	}
}

package io.github.gamemessagepopups;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.TimeUnit;

final class MessageQueue
{
	static final int MAX_VISIBLE = 3;
	static final int MAX_PENDING = 12;
	private static final long MAX_WAIT_NANOS = TimeUnit.SECONDS.toNanos(5);

	private final Deque<Pending> pending = new ArrayDeque<>(MAX_PENDING);
	private List<Popup> visible = List.of();

	synchronized void add(String text, long now, Timing timing)
	{
		if (pending.size() == MAX_PENDING)
		{
			pending.removeFirst();
		}
		pending.addLast(new Pending(text, now + timing.delay, timing));
	}

	synchronized List<Popup> advance(long now)
	{
		Pending next = pending.peekFirst();
		boolean expired = visible.stream().anyMatch(popup -> popup.isExpired(now));
		boolean canShowNext = visible.size() < MAX_VISIBLE && next != null && now - next.readyAt >= 0;
		if (!expired && !canShowNext)
		{
			return visible;
		}

		List<Popup> updated = new ArrayList<>(MAX_VISIBLE);
		for (Popup popup : visible)
		{
			if (!popup.isExpired(now))
			{
				updated.add(popup);
			}
		}

		while (updated.size() < MAX_VISIBLE && next != null && now - next.readyAt >= 0)
		{
			pending.removeFirst();
			if (now - next.readyAt < MAX_WAIT_NANOS)
			{
				updated.add(new Popup(next.text, now, next.timing));
			}
			next = pending.peekFirst();
		}

		visible = List.copyOf(updated);
		return visible;
	}

	synchronized void clear()
	{
		pending.clear();
		visible = List.of();
	}

	static final class Timing
	{
		private final long delay;
		private final long hold;
		private final long fade;

		Timing(int delayMs, int holdMs, int fadeMs)
		{
			delay = millis(delayMs, 0, GameMessagePopupsConfig.MAX_DELAY_MS);
			hold = millis(holdMs, GameMessagePopupsConfig.MIN_HOLD_MS, GameMessagePopupsConfig.MAX_HOLD_MS);
			fade = millis(fadeMs, 0, GameMessagePopupsConfig.MAX_FADE_MS);
		}

		private static long millis(int value, int min, int max)
		{
			return TimeUnit.MILLISECONDS.toNanos(Math.max(min, Math.min(max, value)));
		}
	}

	static final class Popup
	{
		final String text;
		private final long shownAt;
		private final Timing timing;

		private Popup(String text, long shownAt, Timing timing)
		{
			this.text = text;
			this.shownAt = shownAt;
			this.timing = timing;
		}

		boolean isExpired(long now)
		{
			return now - shownAt >= timing.hold + timing.fade;
		}

		float opacity(long now)
		{
			long elapsed = now - shownAt;
			if (elapsed < timing.hold)
			{
				return 1f;
			}
			if (isExpired(now))
			{
				return 0f;
			}
			return 1f - (float) (elapsed - timing.hold) / timing.fade;
		}
	}

	private static final class Pending
	{
		private final String text;
		private final long readyAt;
		private final Timing timing;

		private Pending(String text, long readyAt, Timing timing)
		{
			this.text = text;
			this.readyAt = readyAt;
			this.timing = timing;
		}
	}
}

package io.github.gamemessagepopups;

import java.awt.Font;

public enum PopupFontFamily
{
	SANS_SERIF(Font.SANS_SERIF, "Sans Serif"),
	SERIF(Font.SERIF, "Serif"),
	MONOSPACED(Font.MONOSPACED, "Monospaced"),
	ARIAL("Arial", "Arial"),
	GEORGIA("Georgia", "Georgia"),
	VERDANA("Verdana", "Verdana"),
	COURIER_NEW("Courier New", "Courier New"),
	TIMES_NEW_ROMAN("Times New Roman", "Times New Roman"),
	CUSTOM("", "Custom");

	private final String family;
	private final String label;

	PopupFontFamily(String family, String label)
	{
		this.family = family;
		this.label = label;
	}

	String resolve(String customFamily)
	{
		if (this != CUSTOM)
		{
			return family;
		}
		return customFamily.isBlank() ? Font.SANS_SERIF : customFamily.strip();
	}

	static PopupFontFamily fromSavedName(String savedName)
	{
		String family = savedName.strip();
		if (family.isEmpty())
		{
			return SANS_SERIF;
		}
		for (PopupFontFamily option : values())
		{
			if (option.family.equalsIgnoreCase(family))
			{
				return option;
			}
		}
		return CUSTOM;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

