package io.github.gamemessagepopups;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class MessageLayoutTest
{
	private static final Font FONT = new Font(Font.SANS_SERIF, Font.BOLD, 18);

	@Test
	public void wrapsWordsAndLongUnbrokenStringsWithinTheAvailableWidth()
	{
		int maxWidth = 150;
		int maxHeight = 180;
		MessageLayout shortText = MessageLayout.wrap(List.of("Look out!"), FONT, Color.RED, true, false, maxWidth, maxHeight);
		for (String text : List.of("The spell won't work on this target right now.", "X".repeat(150)))
		{
			MessageLayout wrapped = MessageLayout.wrap(List.of(text), FONT, Color.RED, true, false, maxWidth, maxHeight);
			assertTrue(wrapped.size.width <= maxWidth);
			assertTrue(wrapped.size.height <= maxHeight);
			assertTrue(wrapped.size.height > shortText.size.height);
		}
	}

	@Test
	public void fitsTheStackAtLargeFontSizesAndPrioritizesRecentMessagesInSmallViewports()
	{
		Font large = FONT.deriveFont(48f);
		List<String> messages = List.of("First ".repeat(30), "Second ".repeat(20), "Third");
		MessageLayout layout = MessageLayout.wrap(messages, large, Color.RED, true, false, 496, 318);
		assertTrue(layout.size.width <= 496);
		assertTrue(layout.size.height <= 318);

		MessageLayout oneRow = MessageLayout.wrap(messages, large, Color.RED, true, false, 496, 70);
		MessageLayout newest = MessageLayout.wrap(List.of("Third"), large, Color.RED, true, false, 496, 70);
		assertEquals(newest.size, oneRow.size);
		assertSame(MessageLayout.EMPTY, MessageLayout.wrap(messages, large, Color.RED, true, false, 496, 22));
	}

	@Test
	public void paintsOutlineAndShadowIndependentlyAtTheRequestedOpacity()
	{
		assertDecorations(false, false);
		assertDecorations(true, false);
		assertDecorations(false, true);
		assertDecorations(true, true);
	}

	private static void assertDecorations(boolean outline, boolean shadow)
	{
		MessageLayout layout = MessageLayout.wrap(List.of("Preview"), FONT, Color.RED, outline, shadow, 360, 100);
		BufferedImage image = new BufferedImage(layout.size.width, layout.size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			layout.paint(graphics, new float[] {0.5f});
		}
		finally
		{
			graphics.dispose();
		}

		boolean hasFill = false;
		boolean hasOutline = false;
		boolean hasShadow = false;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int pixel = image.getRGB(x, y);
				int alpha = pixel >>> 24;
				assertTrue(alpha <= 128);
				if (alpha >= 64)
				{
					int red = (pixel >>> 16) & 255;
					hasFill |= red == 255;
					hasOutline |= ((pixel >>> 8) & 255) >= 4;
					hasShadow |= red == 0;
				}
			}
		}
		assertTrue(hasFill);
		assertEquals("outline", outline, hasOutline);
		assertEquals("shadow", shadow, hasShadow);
	}
}

package io.github.gamemessagepopups;

import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class MessageQueueTest
{
	private final MessageQueue queue = new MessageQueue();

	@Test
	public void delayHoldAndFadeUseActualDisplayTime()
	{
		queue.add("first", ms(0), new MessageQueue.Timing(100, 400, 200));
		assertTrue(queue.advance(ms(99)).isEmpty());

		MessageQueue.Popup popup = queue.advance(ms(140)).get(0);
		assertEquals(1f, popup.opacity(ms(539)), 0f);
		assertEquals(1f, popup.opacity(ms(540)), 0f);
		assertEquals(0.5f, popup.opacity(ms(640)), 0.001f);
		assertEquals(0f, popup.opacity(ms(740)), 0f);
		assertTrue(queue.advance(ms(740)).isEmpty());
	}

	@Test
	public void fillsSlotsInOrderWithoutCuttingOffCurrentMessages()
	{
		MessageQueue.Timing timing = new MessageQueue.Timing(0, 400, 0);
		for (String text : List.of("one", "two", "three", "four"))
		{
			queue.add(text, ms(0), timing);
		}

		List<MessageQueue.Popup> initial = queue.advance(ms(0));
		assertEquals(MessageQueue.MAX_VISIBLE, initial.size());
		assertEquals("one", initial.get(0).text);
		assertEquals("three", initial.get(2).text);
		assertEquals(initial, queue.advance(ms(399)));
		List<MessageQueue.Popup> next = queue.advance(ms(400));
		assertEquals(1, next.size());
		assertEquals("four", next.get(0).text);
		assertEquals(1f, next.get(0).opacity(ms(799)), 0f);
		assertTrue(queue.advance(ms(800)).isEmpty());
	}

	@Test
	public void capsTheBacklogAndSkipsStaleMessages()
	{
		MessageQueue.Timing timing = new MessageQueue.Timing(0, 100, 0);
		for (int index = 0; index <= MessageQueue.MAX_PENDING; index++)
		{
			queue.add(Integer.toString(index), ms(0), timing);
		}
		assertEquals("1", queue.advance(ms(0)).get(0).text);
		queue.add("recent", ms(4999), timing);
		List<MessageQueue.Popup> remaining = queue.advance(ms(5000));
		assertEquals(1, remaining.size());
		assertEquals("recent", remaining.get(0).text);
	}

	@Test
	public void clearResetsVisibleAndPendingMessages()
	{
		queue.add("visible", ms(0), new MessageQueue.Timing(0, 100, 0));
		queue.add("pending", ms(0), new MessageQueue.Timing(100, 100, 0));
		assertEquals(1, queue.advance(ms(0)).size());
		queue.clear();
		assertTrue(queue.advance(ms(100)).isEmpty());
	}

	private static long ms(int milliseconds)
	{
		return TimeUnit.MILLISECONDS.toNanos(milliseconds);
	}
}

